mapper.select:
SELECT r.ID, r.PARTNER_ID, r.ASSESSMENT_TYPE, r.RISK_LEVEL, r.RISK_SCORE, r.RISK_STATUS, r.LAST_ASSESSMENT_DATE, r.NEXT_ASSESSMENT_DATE, r.ASSESSMENT_DESCRIPTION, r.CONTROL_MEASURES, r.REMARKS, r.IS_ENABLED, r.CREATE_TIME, r.UPDATE_TIME, r.CREATE_USER, r.UPDATE_USER, r.VERSION_NO, p.PARTNER_CODE, p.PARTNER_NAME, p.PARTNER_TYPE_ID FROM TC_PARTNER_RISK_ASSESSMENT r LEFT JOIN TC_PARTNER_ARCHIVE p ON r.PARTNER_ID = p.ID
AND r.PARTNER_ID = #{params.partnerId}
AND p.PARTNER_CODE LIKE '%' || #{params.partnerCode} || '%'
AND p.PARTNER_NAME LIKE '%' || #{params.partnerName} || '%'
AND r.RISK_LEVEL = #{params.riskLevel}
AND r.RISK_STATUS = #{params.riskStatus}
AND r.ASSESSMENT_TYPE = #{params.assessmentType}
ORDER BY r.CREATE_TIME DESC

SELECT * FROM TC_PARTNER_RISK_ASSESSMENT
WHERE PARTNER_ID = #{partnerId}
ORDER BY CREATE_TIME DESC

SELECT * FROM TC_PARTNER_RISK_ASSESSMENT
WHERE RISK_LEVEL = #{riskLevel}
ORDER BY CREATE_TIME DESC

SELECT * FROM TC_PARTNER_RISK_ASSESSMENT
WHERE RISK_STATUS = #{riskStatus}
ORDER BY CREATE_TIME DESC
